#!/usr/bin/env bash
set -euo pipefail

# WireGuard client setup for macOS
# Installs wireguard-tools via Homebrew and activates the split-tunnel config.
#
# Prerequisites:
#   - Homebrew installed
#   - .conf file generated by client/gen_config.sh
#
# Usage:
#   ./client/setup_macos.sh --config client/output/wg_macbook.conf
#   ./client/setup_macos.sh --config client/output/wg_macbook.conf --autostart

GREEN='\033[0;32m'; YELLOW='\033[1;33m'; RED='\033[0;31m'; CYAN='\033[0;36m'; NC='\033[0m'
info()    { echo -e "${CYAN}[INFO]${NC}  $*"; }
success() { echo -e "${GREEN}[OK]${NC}    $*"; }
warn()    { echo -e "${YELLOW}[WARN]${NC}  $*"; }
error()   { echo -e "${RED}[ERROR]${NC} $*" >&2; exit 1; }
step()    { echo -e "\n${CYAN}=== $* ===${NC}"; }

CONFIG_FILE=""
AUTOSTART=false
WG_IFACE="wg0"

usage() {
    cat <<EOF
Usage: $0 --config CONFIG_FILE [OPTIONS]

Required:
  --config FILE    Path to WireGuard client .conf file

Options:
  --iface NAME     WireGuard interface name (default: wg0)
  --autostart      Install launchd plist to auto-connect on login
  --clean          Remove WireGuard config and stop tunnel
  --help           Show this help

Note: macOS WireGuard App (App Store) is the simplest option for GUI users.
      This script uses wireguard-tools for command-line/automated setups.
EOF
}

CLEAN=false
while [[ $# -gt 0 ]]; do
    case $1 in
        --config)    CONFIG_FILE="$2"; shift 2 ;;
        --iface)     WG_IFACE="$2"; shift 2 ;;
        --autostart) AUTOSTART=true; shift ;;
        --clean)     CLEAN=true; shift ;;
        --help)      usage; exit 0 ;;
        *)           error "Unknown option: $1" ;;
    esac
done

[[ "$(uname)" == "Darwin" ]] || error "This script is for macOS only"

# ---------- Clean mode ----------
if $CLEAN; then
    step "Removing WireGuard tunnel"
    if sudo wg show "$WG_IFACE" &>/dev/null 2>&1; then
        sudo wg-quick down "$WG_IFACE"
        success "Tunnel $WG_IFACE stopped"
    fi
    PLIST_FILE="$HOME/Library/LaunchAgents/com.wireguard.${WG_IFACE}.plist"
    if [[ -f "$PLIST_FILE" ]]; then
        launchctl unload "$PLIST_FILE" 2>/dev/null || true
        rm -f "$PLIST_FILE"
        success "LaunchAgent removed"
    fi
    sudo rm -f "/etc/wireguard/${WG_IFACE}.conf"
    success "Config removed"
    exit 0
fi

[[ -n "$CONFIG_FILE" ]] || error "--config is required (or use --clean)"
[[ -f "$CONFIG_FILE" ]] || error "Config file not found: $CONFIG_FILE"

# ---------- Install wireguard-tools ----------
step "Installing wireguard-tools"
if ! command -v wg &>/dev/null; then
    if command -v brew &>/dev/null; then
        brew install wireguard-tools
        success "wireguard-tools installed"
    else
        error "Homebrew not found. Install from https://brew.sh or install the WireGuard App from App Store."
    fi
else
    success "wireguard-tools already installed: $(wg --version)"
fi

# ---------- Install config ----------
step "Installing WireGuard config"
WG_CONF_DIR="/etc/wireguard"
sudo mkdir -p "$WG_CONF_DIR"
sudo cp "$CONFIG_FILE" "$WG_CONF_DIR/${WG_IFACE}.conf"
sudo chmod 600 "$WG_CONF_DIR/${WG_IFACE}.conf"
success "Config installed: $WG_CONF_DIR/${WG_IFACE}.conf"

# ---------- Start tunnel ----------
step "Starting WireGuard tunnel"
# Stop existing tunnel if running
if sudo wg show "$WG_IFACE" &>/dev/null 2>&1; then
    warn "Tunnel $WG_IFACE already running, restarting..."
    sudo wg-quick down "$WG_IFACE" || true
fi
sudo wg-quick up "$WG_IFACE"
success "Tunnel $WG_IFACE is up"

# Show tunnel status
echo ""
sudo wg show "$WG_IFACE"

# ---------- Autostart via launchd ----------
if $AUTOSTART; then
    step "Installing LaunchAgent for auto-connect on login"
    PLIST_DIR="$HOME/Library/LaunchAgents"
    PLIST_FILE="$PLIST_DIR/com.wireguard.${WG_IFACE}.plist"
    mkdir -p "$PLIST_DIR"

    WG_QUICK=$(command -v wg-quick)
    cat > "$PLIST_FILE" <<PLIST
<?xml version="1.0" encoding="UTF-8"?>
<!DOCTYPE plist PUBLIC "-//Apple//DTD PLIST 1.0//EN"
  "http://www.apple.com/DTDs/PropertyList-1.0.dtd">
<plist version="1.0">
<dict>
    <key>Label</key>
    <string>com.wireguard.${WG_IFACE}</string>
    <key>ProgramArguments</key>
    <array>
        <string>${WG_QUICK}</string>
        <string>up</string>
        <string>${WG_IFACE}</string>
    </array>
    <key>RunAtLoad</key>
    <true/>
    <key>StandardOutPath</key>
    <string>/tmp/wireguard-${WG_IFACE}.log</string>
    <key>StandardErrorPath</key>
    <string>/tmp/wireguard-${WG_IFACE}.err</string>
</dict>
</plist>
PLIST

    launchctl load "$PLIST_FILE"
    success "LaunchAgent installed: $PLIST_FILE"
    info "WireGuard will auto-connect on login"
fi

# ---------- Summary ----------
echo ""
success "========================================"
success " macOS WireGuard setup complete!"
success "========================================"
echo ""
echo "  Interface  : $WG_IFACE"
echo "  Config     : $WG_CONF_DIR/${WG_IFACE}.conf"
echo ""
echo "  Useful commands:"
echo "    Status    : sudo wg show $WG_IFACE"
echo "    Connect   : sudo wg-quick up $WG_IFACE"
echo "    Disconnect: sudo wg-quick down $WG_IFACE"
echo "    Remove    : $0 --clean"
echo ""
echo "  Verify split tunnel:"
echo "    curl -s https://ifconfig.me         # should show Singapore IP"
echo "    curl -s --max-time 5 http://www.baidu.com -o /dev/null -w '%{http_code}'  # should work (direct)"
echo ""
echo "  Alternatively, use the WireGuard App from App Store for GUI management."
echo "  Import the .conf file: File → Import tunnel(s) from file"
echo ""
